      }
    },

    {
      // Company shell and sections: /<slug> and /<slug>/<section>.
      path: `/:companySlug/:section(${COMPANY_SECTION_RE})?`,
      name: 'company-home',
      component: CompanyView,
      meta: { ...mobile('Company', 'more', { hideTopBar: true }), company: true }
