}

/* ── Controls ────────────────────────────────────────────────────────────── */

.company-shell .cp-search {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  min-width: 0;
  height: 42px;
  padding: 0 0.75rem;
  border: 1px solid var(--cp-border);
  border-radius: 11px;
  background: var(--cp-surface-soft);
  color: var(--cp-muted);
  transition: border-color 140ms ease, background-color 140ms ease, box-shadow 140ms ease;
}

.company-shell .cp-search:focus-within {
  border-color: var(--cp-border-strong);
  background: var(--cp-surface);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--cp-lime) 20%, transparent);
}

.company-shell .cp-search input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--cp-text);
  font-size: 15px;
}

.company-shell .cp-search input::placeholder {
  color: var(--cp-muted-soft);
}

.company-shell .cp-kbd {
  display: inline-flex;
  align-items: center;
  gap: 1px;
  border: 1px solid var(--cp-border);
  background: var(--cp-surface);
  color: var(--cp-muted-soft);
  border-radius: 5px;
  padding: 1px 5px;
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
}

.company-shell .cp-icon-btn {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  border-radius: 10px;
  color: var(--cp-muted);
  transition: background-color 140ms ease, color 140ms ease, transform 140ms ease;
}

.company-shell .cp-icon-btn:hover {
  background: var(--cp-surface-soft);
  color: var(--cp-text);
}

.company-shell .cp-icon-btn:active {
  transform: scale(0.96);
}

/* Project selector in the company top bar. A company runs several projects and
   the active one is shown here; switching it keeps the current company section
   so the whole shell follows one project context. */
.company-shell .cp-project-select {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  height: 32px;
  max-width: 190px;
  padding: 0 0.5rem;
  border-radius: 9px;
  background: var(--cp-surface-soft);
  color: var(--cp-text);
  font-size: 11.5px;
  font-weight: 600;
}

.company-shell .cp-project-select select {
  appearance: none;
  background: transparent;
  border: 0;
  color: inherit;
  font: inherit;
  max-width: 150px;
  cursor: pointer;
  outline: none;
}

.company-shell .cp-project-select select option {
  color: var(--cp-text);
  background: var(--cp-surface-soft);
}

.company-shell .cp-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  height: 32px;
  padding: 0 0.65rem;
  border: 1px solid var(--cp-border);
  border-radius: 999px;
  background: var(--cp-surface);
  color: var(--cp-muted);
  font-size: 12.5px;
  font-weight: 600;
  white-space: nowrap;
  transition: border-color 140ms ease, color 140ms ease, background-color 140ms ease;
}

.company-shell .cp-chip:hover {
  border-color: var(--cp-border-strong);
  color: var(--cp-text);
}

.company-shell .cp-chip--solid {
  border-color: transparent;
  background: var(--cp-surface-strong);
  color: var(--cp-text);
}

.company-shell .cp-cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  height: 40px;
  padding: 0 0.9rem;
  border-radius: 10px;
  background: var(--cp-lime);
  color: var(--cp-lime-ink);
  font-size: 15px;
  font-weight: 700;
  transition: background-color 140ms ease, transform 140ms ease;
}

.company-shell .cp-cta:hover {
  background: var(--cp-lime-deep);
}

.company-shell .cp-cta:active {
  transform: translateY(1px);
}

.company-shell .cp-cta-dark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  height: 40px;
  padding: 0 0.9rem;
  border-radius: 10px;
  background: var(--cp-cta-bg);
  color: var(--cp-cta-ink);
  font-size: 15px;
  font-weight: 650;
  transition: background-color 140ms ease, transform 140ms ease;
}

.company-shell .cp-cta-dark:hover {
  background: var(--cp-cta-hover);
}

.company-shell .cp-cta-dark:active {
  transform: translateY(1px);
}

.company-shell .cp-progress {
  position: relative;
  width: 100%;
  height: 9px;
  border-radius: 999px;
  background: var(--cp-track);
  overflow: hidden;
}

.company-shell .cp-progress > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--cp-lime);
  transition: width 500ms cubic-bezier(0.22, 1, 0.36, 1);
}

.company-shell .cp-progress--slim {
  height: 6px;
}

.company-shell .cp-progress--danger > span {
  background: var(--cp-red);
}

/* ── Forms ───────────────────────────────────────────────────────────────── */

.company-shell .cp-field {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  min-width: 0;
}

.company-shell .cp-field > span {
  color: var(--cp-muted);
  font-size: 11.5px;
  font-weight: 650;
  letter-spacing: 0.015em;
}

.company-shell .cp-input,
.company-shell .cp-select,
.company-shell .cp-textarea {
  width: 100%;
  border: 1px solid var(--cp-border);
  border-radius: 9px;
  background: var(--cp-surface);
  color: var(--cp-text);
  font-size: 14px;
  line-height: 1.35;
  padding: 0.48rem 0.62rem;
  outline: none;
  transition: border-color 140ms ease, box-shadow 140ms ease, background-color 140ms ease;
}

.company-shell .cp-input,
.company-shell .cp-select {
  height: 38px;
}

.company-shell .cp-textarea {
  min-height: 58px;
  resize: vertical;
}

.company-shell .cp-input::placeholder,
.company-shell .cp-textarea::placeholder {
  color: var(--cp-muted-soft);
}

.company-shell .cp-input:hover,
.company-shell .cp-select:hover,
.company-shell .cp-textarea:hover {
  border-color: var(--cp-border-strong);
}

.company-shell .cp-input:focus,
.company-shell .cp-select:focus,
.company-shell .cp-textarea:focus {
  border-color: var(--cp-lime);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--cp-lime) 18%, transparent);
}

.company-shell .cp-input:disabled,
.company-shell .cp-select:disabled,
.company-shell .cp-textarea:disabled {
  cursor: not-allowed;
  opacity: 0.55;
  background: var(--cp-surface-soft);
}

.company-shell .cp-help {
  color: var(--cp-muted-soft);
  font-size: 10px;
  line-height: 1.4;
}

.company-shell input[type='checkbox'] {
  accent-color: var(--cp-lime);
}

/* ── Chart ───────────────────────────────────────────────────────────────── */

.company-shell .cp-chart {
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr);
  gap: 10px;
  height: 194px;
}

.company-shell .cp-chart-y {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding-bottom: 24px;
  color: var(--cp-muted-soft);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
}

.company-shell .cp-chart-plot {
  position: relative;
  min-width: 0;
}

.company-shell .cp-chart-lines {
  position: absolute;
  inset: 0 0 24px 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  pointer-events: none;
}

.company-shell .cp-chart-lines > span {
  display: block;
  width: 100%;
  border-top: 1px dashed var(--cp-border);
}

.company-shell .cp-chart-cols {
  position: absolute;
  inset: 0 0 0 0;
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  gap: 4px;
}

.company-shell .cp-chart-col {
  position: relative;
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  height: 100%;
  padding-bottom: 24px;
  min-width: 0;
}

.company-shell .cp-chart-stack {
  width: 100%;
  max-width: 44px;
  min-height: 2px;
  display: flex;
  flex-direction: column-reverse;
  justify-content: flex-start;
  overflow: hidden;
  border-radius: 7px;
  background: var(--cp-chart-bar);
  transition: height 420ms cubic-bezier(0.22, 1, 0.36, 1), background-color 140ms ease;
  transform-origin: bottom;
}

.company-shell .cp-chart-col:hover .cp-chart-stack,
.company-shell .cp-chart-col.is-active .cp-chart-stack {
  background: var(--cp-chart-bar-hover);
}

.company-shell .cp-chart-stack > i {
  display: block;
  width: 100%;
  min-height: 1px;
}

.company-shell .cp-chart-label {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  color: var(--cp-muted-soft);
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
}

.company-shell .cp-chart-col.is-active .cp-chart-label {
  color: var(--cp-text);
}

.company-shell .cp-chart-tooltip {
  position: absolute;
  top: 4px;
  z-index: 5;
  transform: translateX(-50%);
  width: 128px;
  padding: 0.55rem 0.65rem;
  border-radius: 10px;
  background: var(--cp-tooltip);
  color: var(--cp-tooltip-ink);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.2);
  pointer-events: none;
}

.company-shell .cp-chart-tooltip::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 50%;
  width: 8px;
  height: 8px;
  background: var(--cp-tooltip);
  transform: translateX(-50%) rotate(45deg);
}

.company-shell .cp-chart-tooltip-title {
  font-size: 10.5px;
  letter-spacing: 0.04em;
  opacity: 0.6;
  font-weight: 600;
}

.company-shell .cp-chart-tooltip-row {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 11.5px;
  list-style: none;
}

.company-shell .cp-chart-tooltip-row b {
  margin-left: auto;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

.company-shell .cp-quick-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  min-width: 0;
  padding: 0.35rem 0.1rem;
  border-radius: 10px;
  color: var(--cp-muted);
  font-size: 11.5px;
  font-weight: 550;
  transition: background-color 140ms ease, color 140ms ease;
}

.company-shell .cp-quick-btn:hover {
  background: var(--cp-surface-soft);
  color: var(--cp-text);
}

.company-shell .cp-quick-btn i {
  font-size: 17.5px;
  color: var(--cp-text);
}

.company-shell .cp-avatar {
  width: 31px;
  height: 31px;
  border-radius: 999px;
  border: 2px solid var(--cp-surface);
  object-fit: cover;
  background: var(--cp-surface-strong);
}

.company-shell .cp-avatar-fallback {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  flex: 0 0 auto;
  border-radius: 999px;
  border: 2px solid var(--cp-surface);
  background: var(--cp-lime-soft);
  color: var(--cp-accent-ink);
  font-size: 11.5px;
  font-weight: 800;
}

/* ── Lists / activity ────────────────────────────────────────────────────── */

.company-shell .cp-list-row {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  width: 100%;
  min-width: 0;
  border-radius: 10px;
  padding: 0.42rem 0.35rem;
  text-align: left;
  transition: background-color 130ms ease;
}

.company-shell .cp-list-row:hover {
  background: var(--cp-surface-soft);
}

.company-shell .cp-icon-tile {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  flex: 0 0 auto;
  border-radius: 9px;
  background: var(--cp-surface-strong);
  color: var(--cp-muted);
}

.company-shell .cp-icon-tile--lime {
  background: var(--cp-lime-soft);
  color: var(--cp-accent-ink);
}

.company-shell .cp-icon-tile--yellow {
  background: var(--cp-yellow-soft);
  color: var(--cp-secondary-ink);
}

.company-shell .cp-icon-tile--green {
  background: var(--cp-green-soft);
  color: var(--cp-success-ink);
}

.company-shell .cp-icon-tile--red {
  background: var(--cp-red-soft);
  color: var(--cp-error-ink);
}

.company-shell .cp-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  flex: 0 0 auto;
  border-radius: 999px;
  background: currentColor;
}

/* ── Promo / assistant card (sidebar) ────────────────────────────────────── */

.company-shell .cp-promo {
  position: relative;
  overflow: hidden;
  border-radius: 15px;
  padding: 0.85rem;
  background: linear-gradient(155deg, #1b2128, #0d1115);
  color: #f2f5f8;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.company-shell .cp-promo::after {
  content: '';
  position: absolute;
  right: -22px;
  top: -26px;
  width: 84px;
  height: 84px;
  border-radius: 50%;
  background: rgba(220, 75, 183, 0.18);
  filter: blur(2px);
}

.company-shell .cp-promo-badge {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 7px;
  background: var(--cp-lime);
  color: var(--cp-lime-ink);
  font-size: 12.5px;
}

.company-shell .cp-promo-action {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.3rem;
  width: 100%;
  height: 32px;
  border-radius: 8px;
  background: var(--cp-lime);
  color: var(--cp-lime-ink);
  font-size: 12.5px;
  font-weight: 700;
  transition: background-color 140ms ease;
}

.company-shell .cp-promo-action:hover {
  background: var(--cp-lime-bright);
}

/* ── Mosaic decoration (tips card) ───────────────────────────────────────── */

.company-shell .cp-mosaic {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 4px;
  width: 96px;
  transform: rotate(-6deg);
}

.company-shell .cp-mosaic > span {
  aspect-ratio: 1;
  border-radius: 4px;
  background: var(--cp-lime-soft);
}

.company-shell .cp-mosaic > span:nth-child(3n) {
  background: var(--cp-yellow-soft);
}

.company-shell .cp-mosaic > span:nth-child(4n) {
  background: var(--cp-green-soft);
}

.company-shell .cp-mosaic > span:nth-child(5n) {
  background: var(--cp-lime);
}

/* ── Misc ────────────────────────────────────────────────────────────────── */

.company-shell .cp-scroll {
  scrollbar-width: thin;
  scrollbar-color: var(--cp-border-strong) transparent;
}

.company-shell .cp-scroll::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

.company-shell .cp-scroll::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: var(--cp-border-strong);
}

.company-shell .cp-scroll::-webkit-scrollbar-track {
  background: transparent;
}

.company-shell :focus-visible {
  outline: 2px solid color-mix(in oklab, var(--cp-lime-deep) 70%, transparent);
  outline-offset: 2px;
}

/* Keep daisyUI's semantic text utilities readable on the company palette:
   the fills stay bright, only the text tone is deepened. */
.company-shell .text-primary {
  color: var(--cp-accent-ink) !important;
}

.company-shell .text-secondary {
  color: var(--cp-secondary-ink) !important;
}

.company-shell .text-success {
  color: var(--cp-success-ink) !important;
}

.company-shell .text-warning {
  color: var(--cp-warning-ink) !important;
}

.company-shell .text-error {
  color: var(--cp-error-ink) !important;
}

.company-shell .text-info {
  color: var(--cp-info-ink) !important;
}

/* The company views keep their cards flat: daisyUI's default 3D depth reads
   heavy on this canvas. */
.company-shell .modal-box,
.company-shell .dropdown-content {
  border: 1px solid var(--cp-border);
  box-shadow: var(--cp-shadow);
}

.company-shell .btn {
  text-transform: none;
  letter-spacing: 0;
}

.company-shell .btn-primary {
  font-weight: 700;
}

/* ── Motion ──────────────────────────────────────────────────────────────── */

.company-shell .cp-fade-enter-active,
.company-shell .cp-fade-leave-active {
  transition: opacity 160ms ease, transform 160ms ease;
}

.company-shell .cp-fade-enter-from {
  opacity: 0;
  transform: translateY(4px);
}

.company-shell .cp-fade-leave-to {
  opacity: 0;
  transform: translateY(-2px);
}

@media (prefers-reduced-motion: reduce) {
  .company-shell *,
  .company-shell *::before,
  .company-shell *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

@media (max-width: 767px) {
  .company-shell {
    --cp-radius: 16px;
  }

  .company-shell .cp-display {
    font-size: 2.375rem;
  }

  .company-shell .cp-card-pad {
    padding: 0.9rem;
  }

  .company-shell .cp-chart {
    height: 168px;
  }

  .company-shell .cp-chart-stack {
    max-width: 34px;
  }
}


/* The dashboard's analysis row is three cards wide from 1180px: at that width
   the main column is wide enough for the reference layout, while Tailwind's
   named `sm` breakpoint would otherwise win the cascade for grid-template. */
@media (min-width: 1180px) {
  .company-dashboard .company-analysis-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .company-dashboard .company-analysis-grid > .company-goal-card {
    grid-column: auto / span 1;
  }
}


/* Touch layouts get the chart without the floating hover card: on a phone the
   card covers a third of the plot and there is no hover to dismiss it. */
@media (max-width: 520px) {
  .company-shell .cp-chart-tooltip {
    display: none;
  }
}


@media (hover: none) {
  .company-shell .cp-chart-tooltip {
    display: none;
  }
}

/* ── Mobile ergonomics ───────────────────────────────────────────────────── */
/* The dashboard is deliberately dense on desktop. On a phone the same blocks
   stack and the smallest labels are raised to a readable floor; touch targets
   grow to 40px. Inputs stay at 16px to avoid iOS zoom. */
@media (max-width: 767px) {
  .company-shell .cp-card {
    border-radius: 16px;
  }

  .company-shell .cp-icon-btn {
    width: 40px;
    height: 40px;
  }

  .company-shell .cp-cta,
  .company-shell .cp-cta-dark {
    height: 44px;
  }

  .company-shell .cp-input,
  .company-shell .cp-select,
  .company-shell .cp-textarea {
    font-size: 16px;
    min-height: 40px;
  }

  .company-shell .cp-field > span {
    font-size: 13px;
  }

  .company-dashboard [class*='text-[7px]'],
  .company-dashboard [class*='text-[7.5px]'],
  .company-dashboard [class*='text-[8px]'],
  .company-dashboard [class*='text-[8.5px]'] {
    font-size: 13px;
  }

  .company-dashboard [class*='text-[9px]'],
  .company-dashboard [class*='text-[9.5px]'] {
    font-size: 14.5px;
  }

  .company-dashboard [class*='text-[10px]'],
  .company-dashboard [class*='text-[10.5px]'] {
    font-size: 15.5px;
  }

  .company-dashboard .cp-display {
    font-size: 2.5rem;
  }

  .company-shell .cp-quick-btn span {
    display: block;
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

